import {VERSION,PRODUCTION,UPLOAD,PUBLICATION,PLATFORMS,FORMATS,uid,today,dayAdd,monday,validateState,issues,weekItems,demoState,csvState,mergeState,exportCSV,CSV_COLUMNS,movePlan} from './model.js';
const KEY='yayin-koordinatoru.v1',BACKUP=KEY+'.previous';
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let poolFilter='undated',movingId=null;let state,storageError='',view='overview',channelFilter='',search='',pubFilter='',productionFilter='',archived=false,week=monday(today()),editing=null,undo=null,pendingImport=null,toastTimer;
try{const raw=localStorage.getItem(KEY);state=raw?validateState(JSON.parse(raw)):demoState();if(!raw)localStorage.setItem(KEY,JSON.stringify(state));}catch{state={version:VERSION,channels:[],items:[]};storageError='Kayıt alanı okunamadı. Mevcut kayıtların üzerine yazılmadı. Ham yedeği indirip boş alanla yeniden başlayabilirsin.';}
const dateLabel=(s,year=false)=>s?new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short',...(year?{year:'numeric'}:{})}).format(new Date(s.slice(0,10)+'T12:00:00Z')):'Tarih yok';
const timeLabel=s=>s?.slice(11,16)||'';
function toast(text,canUndo=false){clearTimeout(toastTimer);$('#toast-text').textContent=text;$('#undo-button').hidden=!canUndo;$('#toast').hidden=false;toastTimer=setTimeout(()=>{$('#toast').hidden=true;},canUndo?15000:5500);}
function commit(next,message){
 if(storageError){toast('Kayıt alanı sorunu çözülmeden kayıt yapılamaz.');return false;}
 try{const valid=validateState(next);const prev=JSON.stringify(state);localStorage.setItem(BACKUP,prev);localStorage.setItem(KEY,JSON.stringify(valid));undo=state;state=valid;render();toast(message,true);return true;}catch(err){toast('Kaydedilemedi: '+err.message);return false;}
}
function filtered(){return state.items.filter(i=>i.archived===archived&&(!channelFilter||i.channelId===channelFilter)&&(!search||[i.title,i.notes,i.source,state.channels.find(c=>c.id===i.channelId)?.name].join(' ').toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')))&&(!pubFilter||i.publication===pubFilter)&&(!productionFilter||i.production===productionFilter)).sort((a,b)=>(a.plannedAt||'9999').localeCompare(b.plannedAt||'9999'));}
function channelOf(i){return state.channels.find(c=>c.id===i.channelId);}
function badge(value,labels){return `<span class="badge ${esc(value)}">${esc(labels[value])}</span>`;}
function heading(){const info={overview:['Planım','Bir sonraki yayınına yer aç.','İçeriklerini sürükle, haftanı gör, kendi ritmini kur.'],content:['İçerik havuzu','Fikirden son kontrole.','Planı, üretimi ve platform durumunu tek kayıtta tut.'],calendar:['Haftalık takvim','Haftana bir adım uzaktan bak.','Hedef yayın tarihlerini gör; zamanı geçen kayıtları kontrol et.'],channels:['Kanallar','Her kanalın kendi ritmi.','Platformlarını ekle, içeriklerini aynı çalışma alanında yönet.']}[view];$('#breadcrumb').textContent=info[0];$('#page-title').textContent=info[1];$('#page-description').textContent=info[2];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function sidebar(){const active=state.items.filter(i=>!i.archived);$('#nav-count').textContent=active.length;$('#sidebar-channels').innerHTML=state.channels.map(c=>`<button class="channel-nav ${channelFilter===c.id?'active':''}" data-filter-channel="${esc(c.id)}"><span class="dot" style="--dot:${c.color}"></span><span>${esc(c.name)}</span></button>`).join('')||'<span class="subtext">Henüz kanal eklenmedi</span>';$('#demo-banner').hidden=!state.channels.length||!state.channels.every(c=>c.id.startsWith('demo-'));$('#storage-warning').hidden=!storageError;$('#storage-warning').innerHTML=storageError?`${esc(storageError)} <button class="button secondary" id="recover-download">Ham yedeği indir</button><button class="button secondary" id="recover-reset">Boş alanla yeniden başla</button>`:'';}
function stats(){const items=state.items.filter(i=>!i.archived),end=dayAdd(today(),7);const upcoming=items.filter(i=>i.plannedAt&&i.plannedAt.slice(0,10)>=today()&&i.plannedAt.slice(0,10)<end&&i.publication!=='published').length;const ready=items.filter(i=>i.production==='ready'&&i.publication!=='published').length;const needs=items.filter(i=>issues(i).length).length;return `<section class="stats" aria-label="Çalışma alanı özeti">${[[items.length,'Toplam içerik','☷',`${state.channels.length} kanal aynı çalışma alanında`],[ready,'Yayına hazır','✓','Üretimi tamamlanan, yayınlanmamış'],[upcoming,'Önümüzdeki 7 gün','▦',`${dateLabel(today())} – ${dateLabel(dayAdd(today(),6))}`],[needs,'Kontrol bekliyor','◷','Kaynağı veya planı gözden geçir']].map(([n,t,icon,sub])=>`<article class="stat"><div class="stat-top"><span>${t}</span><span class="stat-icon">${icon}</span></div><div class="stat-number">${n}</div><div class="stat-bottom">${esc(sub)}</div></article>`).join('')}</section>`;}
function weekControl(){return `<div class="week-nav"><button class="icon-button" data-week="-1" aria-label="Önceki hafta">‹</button><span class="date-chip">${dateLabel(week)} – ${dateLabel(dayAdd(week,6))}</span><button class="icon-button" data-week="1" aria-label="Sonraki hafta">›</button><button class="text-button" data-this-week>Bu hafta</button></div>`;}
function calendar(full=false){const items=weekItems(state.items.filter(i=>!channelFilter||i.channelId===channelFilter),week);return `<section class="panel"><div class="panel-heading"><div><h2>${full?'Haftalık yayın planı':'Bu haftanın akışı'}</h2><p>Plan tarihleri · Europe/Istanbul</p></div>${weekControl()}</div><div class="${full?'full-calendar':'mini-calendar'}">${Array.from({length:7},(_,n)=>{const day=dayAdd(week,n),events=items.filter(i=>i.plannedAt.startsWith(day));return `<div class="mini-day ${day===today()?'today':''}"><div class="day-title">${new Intl.DateTimeFormat('tr-TR',{weekday:'short'}).format(new Date(day+'T12:00:00Z'))}<b>${Number(day.slice(8))}</b></div>${events.map(i=>{const c=channelOf(i);return `<button class="tiny-event" style="--dot:${c.color}" data-edit="${i.id}" title="${esc(i.title)}"><time>${timeLabel(i.plannedAt)}</time><span>${esc(i.title)}</span>${full?`<div class="event-status">${esc(c.name)}<br>${esc(PUBLICATION[i.publication])}</div>`:''}</button>`;}).join('')||'<div class="mini-empty">·</div>'}</div>`;}).join('')}</div><div class="overview-note">Takvimde bulunmak, içeriğin platformda planlandığını veya yayınlandığını göstermez.</div></section>`;}
function filters(){return `<div class="filters"><label class="search"><span aria-hidden="true">⌕</span><input id="content-search" placeholder="İçerik, kanal veya not ara…" aria-label="İçerik ara" value="${esc(search)}"></label><select id="channel-filter" aria-label="Kanala göre filtrele"><option value="">Tüm kanallar</option>${state.channels.map(c=>`<option value="${c.id}" ${channelFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="pub-filter" aria-label="Yayın durumuna göre filtrele"><option value="">Tüm yayın durumları</option>${options(PUBLICATION,pubFilter)}</select><select id="production-filter" aria-label="Üretime göre filtrele"><option value="">Tüm üretim durumları</option>${options(PRODUCTION,productionFilter)}</select><label class="archive-toggle"><input type="checkbox" id="archive-filter" ${archived?'checked':''}> Arşiv</label>${channelFilter||search||pubFilter||productionFilter||archived?'<button class="text-button" data-clear-filters>Temizle</button>':''}</div>`;}
function table(compact=false){const list=compact?filtered().filter(i=>i.publication!=='published').slice(0,5):filtered();return `<section class="panel ${compact?'section-gap':''}"><div class="panel-heading"><div><h2>${compact?'Sıradaki içerikler':'İçerik havuzu'}</h2><p>${compact?'Hedef tarihe göre sıralı':'Üretim, yükleme ve yayın ayrı ayrı izlenir'}</p></div>${compact?'<button class="text-button" data-view="content">Tümünü gör ↗</button>':'<span class="date-chip">'+filtered().length+' kayıt</span>'}</div>${compact?'':filters()}<div class="table-scroll"><table><thead><tr><th>İÇERİK</th><th>KANAL</th><th>ÜRETİM</th>${compact?'':'<th>YÜKLEME</th>'}<th>YAYIN</th><th>HEDEF TARİH</th>${compact?'':'<th>İŞLEM</th>'}</tr></thead><tbody>${list.map(i=>{const c=channelOf(i),err=issues(i);return `<tr><td><button class="title-button" data-edit="${i.id}">${esc(i.title)}</button><div class="subtext">${esc(i.format)}${i.publishedAt?' · Gerçek yayın: '+dateLabel(i.publishedAt)+' '+timeLabel(i.publishedAt):''}</div>${!compact&&err.length?'<div class="error-inline">'+esc(err[0])+'</div>':''}</td><td><span class="channel-inline"><span class="dot" style="--dot:${c.color}"></span>${esc(c.name)}</span></td><td>${badge(i.production,PRODUCTION)}</td>${compact?'':'<td>'+badge(i.upload,UPLOAD)+'</td>'}<td>${badge(i.publication,PUBLICATION)}</td><td class="date-cell">${dateLabel(i.plannedAt)}<small>${timeLabel(i.plannedAt)}</small></td>${compact?'':`<td><div class="row-actions"><button class="icon-button" data-edit="${i.id}" aria-label="${esc(i.title)} düzenle">✎</button><button class="archive-button" data-archive="${i.id}">${i.archived?'Geri getir':'Arşivle'}</button></div></td>`}</tr>`;}).join('')||`<tr><td colspan="${compact?5:7}" class="table-empty">${state.items.length?'Bu filtrelerde içerik bulunamadı.':'İlk içeriğini ekleyerek başla.'}</td></tr>`}</tbody></table></div><div class="table-footer"><span>${compact?list.length+' içerik gösteriliyor':filtered().length+' içerik · Son değişiklikler bu tarayıcıda saklanır'}</span><span>İstanbul · UTC+3</span></div></section>`;}
function aside(){const active=state.items.filter(i=>!i.archived),pending=active.filter(i=>issues(i).length).slice(0,3);return `<div class="dashboard-aside"><section class="panel"><div class="panel-heading"><h2>Kanalların</h2><button class="text-button" data-view="channels">Yönet ↗</button></div>${state.channels.map(c=>`<div class="channel-card-row"><span class="channel-avatar" style="--dot:${c.color}">${esc(c.name.slice(0,1))}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.platform)}</small></div><span class="count">${active.filter(i=>i.channelId===c.id).length} içerik</span></div>`).join('')||'<div class="table-empty">Henüz kanal yok.</div>'}</section><section class="attention-panel"><h2>◷ &nbsp; Gözden geçir</h2>${pending.map(i=>`<button class="attention-item" data-edit="${i.id}"><b>${esc(i.title)}</b><small>${esc(issues(i)[0])}</small></button>`).join('')||'<p class="attention-empty">Şu an açık bir kontrol yok.</p>'}</section></div>`;}
function channels(){return `<div class="view-heading"><div><h2>${state.channels.length} kanal, tek çalışma alanı</h2><p>Kanallarının içeriklerini ve yayın ritmini düzenle.</p></div><button class="button secondary" id="add-channel-main">+ Kanal ekle</button></div><div class="channel-grid">${state.channels.map(c=>{const items=state.items.filter(i=>!i.archived&&i.channelId===c.id);return `<article class="channel-tile"><div class="channel-tile-top"><div class="channel-avatar" style="--dot:${c.color}">${esc(c.name.slice(0,1))}</div><button class="icon-button" data-edit-channel="${c.id}" aria-label="${esc(c.name)} kanalını düzenle">✎</button></div><h2>${esc(c.name)}</h2><p>${esc(c.platform)}</p><div class="channel-tile-stats">${[[items.length,'İçerik'],[items.filter(i=>i.publication==='scheduled').length,'Planlandı'],[items.filter(i=>i.publication==='published').length,'Yayınlandı']].map(([n,t])=>`<div><b>${n}</b><span>${t}</span></div>`).join('')}</div>${c.url?`<a class="channel-url" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Kanalı aç ↗</a>`:''}<button class="text-button" style="margin-top:18px;display:block" data-filter-channel="${c.id}">İçeriklerini gör →</button></article>`;}).join('')}</div>${state.channels.length?'':empty('İlk kanalını ekle.','Çalışma alanını kendi yayın akışına göre kur.','Kanal ekle','add-channel-main-empty')}`;}
function empty(title,sub,cta,id){return `<div class="empty-state"><div class="eyebrow">YENİ BİR BAŞLANGIÇ</div><h2>${title}</h2><p>${sub}</p><button class="button primary" id="${id}">${cta}</button></div>`;}
function plannerCard(i,pool=false){const c=channelOf(i);const stateLabel=i.publication==='published'?'Yayınlandı':i.publication==='scheduled'?'Platformda planlı':i.upload==='uploaded'?'Yüklendi':PRODUCTION[i.production];return `<article class="plan-card ${i.publication==='published'?'completed':''}" style="--card-color:${c.color}" draggable="${i.publication!=='published'}" data-drag-id="${i.id}"><div class="plan-card-top"><span class="plan-channel"><span class="dot" style="--dot:${c.color}"></span>${esc(c.name)}</span><span class="card-grip" aria-hidden="true">⠿</span></div><button class="plan-card-title" data-edit="${i.id}">${esc(i.title)}</button>${i.platformPlannedAt&&i.platformPlannedAt!==i.plannedAt?'<div class="plan-mismatch">Hedef değişti · platformu kontrol et</div>':''}<div class="plan-card-format">${esc(i.format)}${i.plannedAt&&pool?' · '+dateLabel(i.plannedAt):''}</div><div class="plan-card-bottom"><span class="plan-status ${i.production==='ready'?'ready':''}"><span></span>${esc(stateLabel)}</span>${i.plannedAt&&!pool?'<time>'+timeLabel(i.plannedAt)+'</time>':''}</div>${i.publication!=='published'?`<button class="move-card" data-move="${i.id}" aria-label="${esc(i.title)} güne taşı">Güne taşı <span>↗</span></button>`:''}</article>`;}
function plannerBoard(){const active=state.items.filter(i=>!i.archived&&(!channelFilter||i.channelId===channelFilter));const undated=active.filter(i=>!i.plannedAt&&i.publication!=='published');const ready=active.filter(i=>i.production==='ready'&&i.publication!=='published');const pool=poolFilter==='ready'?ready:undated;const events=weekItems(active,week);const nextWeek=dayAdd(monday(today()),7);return `<div class="planner-controls"><div class="week-segments"><button data-jump-week="${monday(today())}" class="${week===monday(today())?'selected':''}">Bu hafta</button><button data-jump-week="${nextWeek}" class="${week===nextWeek?'selected':''}">Gelecek hafta</button></div><div class="board-date-nav"><button class="icon-button" data-week="-1" aria-label="Önceki hafta">‹</button><h2>${dateLabel(week)} — ${dateLabel(dayAdd(week,6),true)}</h2><button class="icon-button" data-week="1" aria-label="Sonraki hafta">›</button></div><select id="board-channel" aria-label="Kanala göre filtrele"><option value="">Tüm kanallar</option>${state.channels.map(c=>`<option value="${c.id}" ${c.id===channelFilter?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="visual-planner"><aside class="content-pool" data-drop-day=""><div class="pool-heading"><span class="pool-icon">▧</span><h2>İçerik havuzu</h2><span>${pool.length}</span></div><p>Bir fikir burada başlar.<br>Hazır olduğunda bir güne taşı.</p><div class="pool-tabs"><button data-pool="undated" class="${poolFilter==='undated'?'active':''}">Tarihsiz <span>${undated.length}</span></button><button data-pool="ready" class="${poolFilter==='ready'?'active':''}">Hazır <span>${ready.length}</span></button></div><div class="pool-cards">${pool.map(i=>plannerCard(i,true)).join('')||'<div class="pool-empty"><span>◌</span><p>Burada biraz boşluk var.<br>Yeni bir içerik ekleyebilirsin.</p></div>'}</div><button class="pool-add" id="pool-add">+ İçerik ekle</button><div class="pool-tip">Kartları bir güne sürükle.<br>İstersen “Güne taşı” seçeneğini kullan.</div></aside><section class="week-board" aria-label="Haftalık içerik panosu">${Array.from({length:7},(_,n)=>{const day=dayAdd(week,n),list=events.filter(i=>i.plannedAt.startsWith(day));return `<section class="day-column ${day===today()?'is-today':''}" data-drop-day="${day}" aria-label="${dateLabel(day,true)}"><div class="column-heading"><div><span>${new Intl.DateTimeFormat('tr-TR',{weekday:'long'}).format(new Date(day+'T12:00:00Z'))}</span><b>${Number(day.slice(8))}</b></div><span class="day-count">${list.length||'·'}</span></div><div class="column-cards">${list.map(i=>plannerCard(i)).join('')}</div><button class="day-add" data-add-day="${day}" aria-label="${dateLabel(day)} gününe içerik ekle">+</button>${list.length?'':'<div class="drop-hint">Buraya bırak</div>'}</section>`;}).join('')}</section></div><div class="board-summary"><span><b>${events.length}</b> içerik bu haftada</span><span><i class="summary-dot green"></i> ${events.filter(i=>i.publication==='published').length} yayınlandı</span><span><i class="summary-dot purple"></i> ${events.filter(i=>i.publication==='scheduled').length} platformda planlı</span><span><i class="summary-dot orange"></i> ${events.filter(i=>i.upload==='uploaded').length} yüklendi</span><span class="board-summary-note">Kart taşımak yalnız hedef tarihi değiştirir.</span></div>`;}
function render(){heading();sidebar();$('#app-view').innerHTML=view==='overview'||view==='calendar'?plannerBoard():view==='content'?table():channels();bindView();bindBoard();}
function bindBoard(){document.querySelectorAll('[data-jump-week]').forEach(b=>b.onclick=()=>{week=b.dataset.jumpWeek;render();});document.querySelectorAll('[data-pool]').forEach(b=>b.onclick=()=>{poolFilter=b.dataset.pool;render();});if($('#board-channel'))$('#board-channel').onchange=e=>{channelFilter=e.target.value;render();};if($('#pool-add'))$('#pool-add').onclick=()=>editContent();document.querySelectorAll('[data-add-day]').forEach(b=>b.onclick=()=>{editContent();const input=$('#editor-form [name="plannedAt"]');if(input)input.value=b.dataset.addDay+'T18:00';});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>openMove(b.dataset.move));
 document.querySelectorAll('[data-drag-id]').forEach(card=>{bindPointerDrag(card);card.addEventListener('dragstart',e=>{if(card.draggable){e.dataTransfer.setData('text/plain',card.dataset.dragId);e.dataTransfer.effectAllowed='move';card.classList.add('is-dragging');}});card.addEventListener('dragend',()=>{card.classList.remove('is-dragging');document.querySelectorAll('.drop-active').forEach(x=>x.classList.remove('drop-active'));});});
 document.querySelectorAll('[data-drop-day]').forEach(day=>{day.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='move';day.classList.add('drop-active');});day.addEventListener('dragleave',e=>{if(!day.contains(e.relatedTarget))day.classList.remove('drop-active');});day.addEventListener('drop',e=>{e.preventDefault();day.classList.remove('drop-active');const id=e.dataTransfer.getData('text/plain');try{commit(movePlan(state,id,day.dataset.dropDay),day.dataset.dropDay?'Hedef gün güncellendi.':'İçerik tarihsiz havuza taşındı.');}catch(err){toast(err.message);}});});}
function bindPointerDrag(card){const grip=card.querySelector('.card-grip');if(!grip||!card.draggable)return;grip.style.touchAction='none';grip.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();const startX=e.clientX,startY=e.clientY,id=card.dataset.dragId;let moving=false,target=null,ghost=null;grip.setPointerCapture(e.pointerId);const cleanup=()=>{card.classList.remove('is-dragging');ghost?.remove();document.querySelectorAll('.drop-active').forEach(x=>x.classList.remove('drop-active'));grip.removeEventListener('pointermove',move);grip.removeEventListener('pointerup',end);grip.removeEventListener('pointercancel',cancel);};const move=ev=>{if(!moving&&Math.hypot(ev.clientX-startX,ev.clientY-startY)>6){moving=true;card.classList.add('is-dragging');ghost=document.createElement('div');ghost.className='drag-ghost';ghost.textContent=state.items.find(i=>i.id===id).title;document.body.append(ghost);}if(!moving)return;ghost.style.left=ev.clientX+12+'px';ghost.style.top=ev.clientY+12+'px';document.querySelectorAll('.drop-active').forEach(x=>x.classList.remove('drop-active'));target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-drop-day]')||null;target?.classList.add('drop-active');};const end=ev=>{const day=target?.dataset.dropDay;cleanup();if(moving&&day!==undefined){try{commit(movePlan(state,id,day),day?'Hedef gün güncellendi.':'İçerik havuza taşındı.');}catch(err){toast(err.message);}}};const cancel=()=>cleanup();grip.addEventListener('pointermove',move);grip.addEventListener('pointerup',end);grip.addEventListener('pointercancel',cancel);});}
function openMove(id){movingId=id;const item=state.items.find(i=>i.id===id);$('#move-content-title').textContent=item.title;$('#move-day').value=item.plannedAt?.slice(0,10)||week;$('#move-error').textContent='';$('#move-dialog').showModal();}
$('#move-form').onsubmit=e=>{e.preventDefault();try{if(commit(movePlan(state,movingId,$('#move-day').value),'Hedef gün güncellendi.'))$('#move-dialog').close();}catch(err){$('#move-error').textContent=err.message;}};$('#close-move').onclick=$('#cancel-move').onclick=()=>$('#move-dialog').close();
function setView(v){view=v;if(v==='overview'){week=monday(today());channelFilter='';search='';pubFilter='';productionFilter='';archived=false;}render();}
function bindView(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-filter-channel]').forEach(b=>b.onclick=()=>{channelFilter=b.dataset.filterChannel;view='content';render();});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editContent(b.dataset.edit));document.querySelectorAll('[data-edit-channel]').forEach(b=>b.onclick=()=>editChannel(b.dataset.editChannel));document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>{const i=state.items.find(i=>i.id===b.dataset.archive);commit({...state,items:state.items.map(x=>x.id===i.id?{...x,archived:!x.archived}:x)},i.archived?'İçerik geri getirildi.':'İçerik arşivlendi.');});document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{week=dayAdd(week,Number(b.dataset.week)*7);render();});document.querySelectorAll('[data-this-week]').forEach(b=>b.onclick=()=>{week=monday(today());render();});document.querySelectorAll('[data-clear-filters]').forEach(b=>b.onclick=()=>{channelFilter='';search='';pubFilter='';productionFilter='';archived=false;render();});
 const input=$('#content-search');if(input)input.oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#content-search').focus();$('#content-search').setSelectionRange(pos,pos);};
 for(const [id,setter] of [['channel-filter',v=>channelFilter=v],['pub-filter',v=>pubFilter=v],['production-filter',v=>productionFilter=v]])if($('#'+id))$('#'+id).onchange=e=>{setter(e.target.value);render();};
 if($('#archive-filter'))$('#archive-filter').onchange=e=>{archived=e.target.checked;render();};
 for(const id of ['add-channel-main','add-channel-main-empty'])if($('#'+id))$('#'+id).onclick=()=>editChannel();
 if($('#recover-download'))$('#recover-download').onclick=()=>{let raw;try{raw=localStorage.getItem(KEY);}catch{}download(raw||'Kayıt alanına erişilemiyor.','kurtarma-yedegi.txt','text/plain');};
 if($('#recover-reset'))$('#recover-reset').onclick=()=>$('#confirm-dialog').showModal();
}
function options(labels,selected){return Object.entries(labels).map(([k,v])=>`<option value="${esc(k)}" ${k===selected?'selected':''}>${esc(v)}</option>`).join('');}
function field(label,name,value='',type='text',extra=''){return `<label class="field ${['title','notes','source','asset','url','name'].includes(name)?'wide':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,labels,value){return `<label class="field">${label}<select name="${name}">${options(labels,value)}</select></label>`;}
function editContent(id){if(!state.channels.length){editChannel();toast('Önce bir kanal ekle, sonra içeriğini oluştur.');return;}const i=state.items.find(i=>i.id===id)||{channelId:channelFilter||state.channels[0].id,format:'Uzun video',production:'draft',upload:'unknown',publication:'unknown'};editing={kind:'item',id};$('#editor-title').textContent=id?'İçeriği düzenle':'Yeni içerik';$('#editor-fields').innerHTML=`<div class="field-grid">${field('İçerik başlığı *','title',i.title,'text','required maxlength="200"')}${selectField('Kanal *','channelId',Object.fromEntries(state.channels.map(c=>[c.id,c.name])),i.channelId)}${selectField('Format','format',Object.fromEntries(FORMATS.map(x=>[x,x])),i.format)}<div class="field-section">ÜRETİM VE PLATFORM DURUMU</div>${selectField('Üretim','production',PRODUCTION,i.production)}${selectField('Yükleme','upload',UPLOAD,i.upload)}${selectField('Yayın','publication',PUBLICATION,i.publication)}${field('Hedef plan tarihi · İstanbul','plannedAt',i.plannedAt,'datetime-local')}${field('Platformdaki plan tarihi · İstanbul','platformPlannedAt',i.platformPlannedAt,'datetime-local')}${field('Gerçek yayın tarihi · İstanbul','publishedAt',i.publishedAt,'datetime-local')}${field('Son kontrol · İstanbul','verifiedAt',i.verifiedAt,'datetime-local')}<div class="field-section">KAYNAK VE NOTLAR</div>${field('Video bağlantısı','url',i.url,'url','maxlength="500" placeholder="https://…"')}${field('Kaynak / kontrolün dayanağı','source',i.source,'text','maxlength="2000" placeholder="Örn. Studio kontrolü veya yerel dosya planı"')}${field('Dosya referansı','asset',i.asset,'text','maxlength="2000" placeholder="Dosya adı veya klasör notu"')}<label class="field wide">Notlar<textarea name="notes" maxlength="2000">${esc(i.notes||'')}</textarea></label><div class="field wide"><small>Hedef tarih, platform planı anlamına gelmez. Yayınlandı durumunda gerçek yayın tarihini de gir.</small></div></div>`;$('#form-error').textContent='';$('#editor').showModal();}
function editChannel(id){const c=state.channels.find(c=>c.id===id)||{name:'',platform:'YouTube',color:'#7160d9',url:''};editing={kind:'channel',id};$('#editor-title').textContent=id?'Kanalı düzenle':'Yeni kanal';$('#editor-fields').innerHTML=`<div class="field-grid">${field('Kanal adı *','name',c.name,'text','required maxlength="100"')}${selectField('Platform','platform',Object.fromEntries(PLATFORMS.map(x=>[x,x])),c.platform)}${field('Kanal rengi','color',c.color,'color')}${field('Kanal bağlantısı','url',c.url,'url','maxlength="500" placeholder="https://…"')}</div>`;$('#form-error').textContent='';$('#editor').showModal();}
$('#editor-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));try{let next;if(editing.kind==='channel'){const c={...values,id:editing.id||uid()};next={...state,channels:editing.id?state.channels.map(x=>x.id===c.id?c:x):[...state.channels,c]};}else{const prev=state.items.find(i=>i.id===editing.id);const item={...values,id:editing.id||uid(),archived:prev?.archived||false};next={...state,items:editing.id?state.items.map(x=>x.id===item.id?item:x):[...state.items,item]};}validateState(next);if(commit(next,'Kaydedildi.'))$('#editor').close();else $('#form-error').textContent='Kayıt yapılamadı. Tarayıcının yerel kayıt alanını kontrol et.';}catch(err){$('#form-error').textContent=err.message;}};
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Dosya indirmeye hazırlandı.');}
function openData(){pendingImport=null;$('#import-preview').hidden=true;$('#import-error').textContent='';$('#import-file').value='';$('#data-dialog').showModal();}
function previewImport(incoming){
 const next=mergeState(state,incoming);if(!incoming.items.length&&!incoming.channels.length)throw Error('Dosyada içe alınacak kayıt yok.');const updated=incoming.items.filter(i=>state.items.some(x=>x.id===i.id)).length;pendingImport=next;$('#import-preview').innerHTML=`<strong>Önizleme</strong><p>${incoming.channels.length} kanal kaydı, ${incoming.items.length-updated} yeni içerik, ${updated} güncellenecek içerik.</p><p>Birleştirmeden sonra ${next.channels.length} kanal ve ${next.items.length} içerik olacak. Aynı kimlikteki kayıtların dosyadaki notları da uygulanır.</p><button class="button primary" id="apply-import">İnceledim, birleştir</button>`;$('#import-preview').hidden=false;$('#apply-import').onclick=()=>{if(pendingImport&&commit(pendingImport,'Veriler birleştirildi.')){$('#data-dialog').close();pendingImport=null;}};
}
$('#import-file').onchange=async e=>{pendingImport=null;$('#import-preview').hidden=true;$('#import-error').textContent='';const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Dosya 2 MB sınırını aşıyor.');const text=await file.text();previewImport(file.name.toLowerCase().endsWith('.csv')?csvState(text,state):validateState(JSON.parse(text)));}catch(err){$('#import-error').textContent='İçe aktarılamadı: '+err.message;}};
$('#preview-paste').onclick=()=>{pendingImport=null;$('#import-preview').hidden=true;$('#import-error').textContent='';try{const text=$('#import-text').value;if(new Blob([text]).size>2*1024*1024)throw Error('Metin 2 MB sınırını aşıyor.');previewImport(validateState(JSON.parse(text)));}catch(err){$('#import-error').textContent='İçe aktarılamadı: '+err.message;}};
$('#export-json').onclick=()=>download(JSON.stringify(state,null,2),'yayin-koordinatoru-'+today()+'.json','application/json');$('#export-csv').onclick=()=>download(exportCSV(state),'yayin-koordinatoru-'+today()+'.csv','text/csv;charset=utf-8');$('#download-demo').onclick=()=>download(JSON.stringify(demoState(),null,2),'ornek-calisma-alani.json','application/json');$('#download-template').onclick=()=>download('\uFEFF'+CSV_COLUMNS.join(',')+'\r\n','yayin-csv-sablonu.csv','text/csv;charset=utf-8');
$('#data-button').onclick=openData;$('#import-button').onclick=()=>editChannel();$('#new-content').onclick=()=>editContent();$('#add-channel-side').onclick=()=>editChannel();$('#empty-workspace').onclick=()=>$('#confirm-dialog').showModal();$('#help-button').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();$('#cancel-confirm').onclick=()=>$('#confirm-dialog').close();
$('#confirm-empty').onclick=()=>{if(storageError){try{localStorage.setItem(BACKUP,localStorage.getItem(KEY)||'');localStorage.removeItem(KEY);storageError='';}catch{toast('Tarayıcı kayıt alanı kullanılamıyor.');return;}}if(commit({version:1,channels:[],items:[]},'Boş çalışma alanı oluşturuldu.')){$('#confirm-dialog').close();view='channels';render();}};
$('#undo-button').onclick=()=>{if(!undo)return;const prev=undo;if(commit(prev,'Son değişiklik geri alındı.')){$('#undo-button').hidden=true;undo=null;}};
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>$('#editor').close());document.querySelectorAll('.close-data').forEach(b=>b.onclick=()=>$('#data-dialog').close());
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=e.newValue?validateState(JSON.parse(e.newValue)):{version:1,channels:[],items:[]};state=next;undo=null;render();if($('#editor').open){$('#editor').close();toast('Başka sekmedeki kayıt uygulandı. Güncel içerikle tekrar düzenle.');}else toast('Diğer sekmedeki değişiklikler alındı.');}catch{toast('Diğer sekmedeki veri okunamadı; mevcut görünüm korundu.');}}});
render();
